function h(t){if(!t)return null;let n=new Date(String(t).replace(" ","T"));return Number.isNaN(n.getTime())?null:n}function o(t,n){return`${t} ${n}${t===1?"":"s"}`}function r(t,n){return`${o(t,n)} ago`}function l(t,n=Date.now()){let i=Math.max(0,Math.floor((n-t.getTime())/1e3));if(i<60)return r(i,"second");let s=Math.floor(i/60);if(s<60)return r(s,"minute");let f=Math.floor(s/60);if(f<24)return r(f,"hour");let a=Math.floor(f/24);if(a<30)return r(a,"day");let e=Math.floor(a/30);if(e<12){let c=a%30;return c>0?`${o(e,"month")}, ${o(c,"day")} ago`:r(e,"month")}let u=Math.floor(e/12),m=e%12;return m>0?`${o(u,"year")}, ${o(m,"month")} ago`:r(u,"year")}export{h as a,l as b};
